// Create + persist a research task from a plan.
app.post('/research/task', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const code = String(body?.code ?? '').toUpperCase()
  if (!code) return c.json({ error: 'body.code is required' }, 400)
  const plan = body?.kind === 'contract'
    ? planContract(String(body?.contractType ?? 'lease'), code)
    : planJurisdiction(code, body?.name)
  const row = await prisma.researchTask.create({
    data: {
      kind: plan.kind, target: plan.target, jurisdictionCode: code, status: 'open',
      rationale: plan.rationale, officialSources: JSON.stringify(plan.officialSources),
      checklist: JSON.stringify(plan.checklist),
    },
  })
  return c.json({ ok: true, task: { ...row, plan } })
})

// Run the LLM research-assist on a task (zero-cost in-pod). Output is an
// UNVERIFIED candidate; it is stored on the task and the task moves to `drafted`.
app.post('/research/task/:id/assist', async (c) => {
  const task = await prisma.researchTask.findUnique({ where: { id: c.req.param('id') } })
  if (!task) return c.json({ error: 'task not found' }, 404)
  const name = KNOWN_REGISTRIES[task.jurisdictionCode]?.name ?? task.target
  incrementEngineCall('researchAssist')
  const result = await assistJurisdictionResearch(task.jurisdictionCode, name)
  if (!result.ok) return c.json({ ok: false, llmAvailable: llmAvailable(), error: result.error }, 200)
  await prisma.researchTask.update({
    where: { id: task.id },
    data: { status: 'drafted', findings: JSON.stringify({ model: result.model, candidate: result.candidate, raw: result.raw, disclaimer: 'AI candidate — unverified. Must clear the database-vs-originals gate before it is citable.' }) },
  })
  return c.json({ ok: true, model: result.model, candidate: result.candidate, raw: result.raw })
})

// Structure a raw finding into a validated draft (deterministic; conviction pending).
app.post('/research/structure', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  if (!body?.kind || !body?.jurisdictionCode || !body?.title) return c.json({ error: 'kind, jurisdictionCode and title are required' }, 400)
  return c.json(structureFinding(body))
})

// The database-vs-originals gate: promote a draft to a verified record. Requires
// a reviewer identity AND explicit cross-check against the original source.
app.post('/research/promote', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const draft = body?.draft
  if (!draft) return c.json({ error: 'body.draft is required' }, 400)
  const result = promoteDraft(draft, body?.reviewer ?? '', Boolean(body?.crossCheckedAgainstOriginal))
  if (!result.ok) return c.json({ ok: false, blockedBy: result.blockedBy }, 200)
  const rec = result.record!
  if (rec.kind === 'jurisdiction') {
    await prisma.jurisdictionRecord.upsert({
      where: { code: rec.jurisdictionCode },
      update: { name: rec.title, status: 'verified', conviction: 'verified', lastReviewed: new Date() },
      create: { code: rec.jurisdictionCode, name: rec.title, tenureSystem: rec.covers, registryUrl: rec.url, status: 'verified', conviction: 'verified' },
    })
  } else if (rec.kind === 'statute') {
    await prisma.statuteRecord.create({
      data: { jurisdictionCode: rec.jurisdictionCode, shortTitle: rec.title, citation: rec.citation, url: rec.url, covers: rec.covers, status: 'verified', conviction: 'verified', provenance: JSON.stringify(rec.provenance) },
    })
  }
  return c.json({ ok: true, record: rec })
})

