// ── Land-intelligence API (read-only, provenance-tracked) ───────────────────
// Exposes the data spine: jurisdictions, statutes, tiered sources, and a
// computed land-intelligence profile per jurisdiction. Deterministic.

const SPINE_SNAPSHOT = '2026-08-05T14:02:00Z'

// Sources that feed a given jurisdiction: all supra-national (tier 0),
// open-map (1.5) and climate/macro (3) sources, plus that jurisdiction's own.
function sourcesForJurisdiction(code: JurisdictionCode) {
  return SOURCES.filter((s) => !s.jurisdiction || s.jurisdiction === code || s.tier === 0 || s.tier === 1.5 || s.tier === 3)
}

app.get('/spine/jurisdictions', (c) => {
  return c.json({
    snapshot: SPINE_SNAPSHOT,
    count: JURISDICTIONS.length,
    pilot: JURISDICTIONS.filter((j) => j.inPilot).map((j) => j.code),
    jurisdictions: JURISDICTIONS.map((j) => ({
      code: j.code, name: j.name, capital: j.capital, tenureSystem: j.tenureSystem,
      registry: j.registry, climate: j.climate, inPilot: j.inPilot, pilotResidents: j.pilotResidents,
    })),
  })
})

app.get('/spine/sources', (c) => {
  const byTier: Record<string, number> = {}
  const byConviction: Record<string, number> = {}
  for (const s of SOURCES) {
    byTier[String(s.tier)] = (byTier[String(s.tier)] ?? 0) + 1
    byConviction[s.conviction] = (byConviction[s.conviction] ?? 0) + 1
  }
  return c.json({ snapshot: SPINE_SNAPSHOT, count: SOURCES.length, byTier, byConviction, sources: SOURCES })
})

app.get('/spine/summary', (c) => {
  const pilot = JURISDICTIONS.filter((j) => j.inPilot)
  const verifiedStatutes = STATUTES.filter((s) => s.conviction === 'verified').length
  const verifiedSources = SOURCES.filter((s) => s.conviction === 'verified').length
  const verifiedRegistries = JURISDICTIONS.filter((j) => j.registry.conviction === 'verified').length
  return c.json({
    snapshot: SPINE_SNAPSHOT,
    jurisdictions: { total: JURISDICTIONS.length, pilot: pilot.length, roadmap: JURISDICTIONS.length - pilot.length },
    pilotResidents: pilot.reduce((a, j) => a + j.pilotResidents, 0),
    statutes: { total: STATUTES.length, verified: verifiedStatutes },
    sources: { total: SOURCES.length, verified: verifiedSources },
    registryCoverage: { verified: verifiedRegistries, total: JURISDICTIONS.length, pct: Math.round((verifiedRegistries / JURISDICTIONS.length) * 100) },
    hiddenRights: HIDDEN_RIGHTS.length,
  })
})

app.get('/land/:code', (c) => {
  const code = c.req.param('code').toUpperCase() as JurisdictionCode
  const j = JURISDICTIONS.find((x) => x.code === code)
  if (!j) {
    return c.json({ error: `unknown jurisdiction "${code}". Known: ${JURISDICTIONS.map((x) => x.code).join(', ')}` }, 404)
  }
  const statutes = STATUTES.filter((s) => s.jurisdiction === code)
  const feeds = sourcesForJurisdiction(code)
  const verifiedFeeds = feeds.filter((s) => s.conviction === 'verified').length
  // Deterministic data-sufficiency: registry conviction + verified-feed density.
  const registryScore = j.registry.conviction === 'verified' ? 40 : j.registry.conviction === 'inference' ? 15 : 5
  const feedScore = Math.round((verifiedFeeds / feeds.length) * 45)
  const statuteScore = Math.min(15, statutes.length * 5)
  const dataSufficiency = Math.min(100, registryScore + feedScore + statuteScore)
  return c.json({
    snapshot: SPINE_SNAPSHOT,
    jurisdiction: { code: j.code, name: j.name, capital: j.capital, tenureSystem: j.tenureSystem, climate: j.climate, inPilot: j.inPilot },
    registry: j.registry,
    statutes: statutes.map((s) => ({ id: s.id, shortTitle: s.shortTitle, citation: s.citation, url: s.url, covers: s.covers, conviction: s.conviction })),
    feeds: feeds.map((s) => ({ id: s.id, name: s.name, tier: s.tier, gives: s.gives, license: s.license, conviction: s.conviction, url: s.url })),
    dataSufficiency,
    band: dataSufficiency >= 75 ? 'high' : dataSufficiency >= 60 ? 'medium' : dataSufficiency >= 40 ? 'low' : 'abstain',
  })
})

// Consensus/alignment gate (Tier 3). Cross-checks a codified estimate against a
// RAG-agentic estimate for the same claim; enforces honesty by construction.
app.post('/consensus/check', async (c) => {
  const body = await c.req.json().catch(() => null)
  if (!body || (!body.codified && !body.agentic)) {
    return c.json({ error: 'provide at least one of { codified, agentic } estimates (protocol DSP-6)' }, 400)
  }
  try {
    // Jurisdiction maturity is computed dynamically from the spine and drives
    // how much corroboration the gate demands before surfacing a claim.
    const maturity = body.jurisdiction ? maturityFor(String(body.jurisdiction)) : undefined
    incrementEngineCall('consensusCheck')
    const result = reachConsensus(body.codified ?? null, body.agentic ?? null, { maturity })
    return c.json({ ...result, jurisdiction: body.jurisdiction ?? null, appliedMaturity: maturity ?? 'established' })
  } catch (e) {
    return c.json({ error: e instanceof Error ? e.message : 'consensus failed' }, 400)
  }
})

// HITL decision endpoint — human approves or rejects a divergent consensus result.
// Logs the decision to the Signoff model as an immutable audit record.
app.post('/consensus/decide', async (c) => {
  const body = await c.req.json().catch(() => null)
  if (!body || !body.decision || !['approve', 'reject'].includes(body.decision)) {
    return c.json({ error: 'provide { decision: "approve" | "reject", claim, rationale?, jurisdiction? }' }, 400)
  }
  try {
    const claim = String(body.claim ?? 'unlabelled-claim').slice(0, 250)
    const rationale = String(body.rationale ?? '').slice(0, 1000)
    const jurisdiction = String(body.jurisdiction ?? 'UNKNOWN').slice(0, 10)
    const decisionValue = body.decision === 'approve' ? 'hitl-reviewed' : 'rejected'
    const rowHash = Buffer.from(`${claim}:${decisionValue}:${Date.now()}`).toString('base64').slice(0, 44)
    const signoff = await prisma.signoff.create({
      data: {
        residentId: 'demo-hitl',
        jurisdiction,
        decision: decisionValue,
        signOff: JSON.stringify({ claim, verdict: body.decision, source: 'live-demo-hitl' }),
        rowHash,
        reviewer: 'human',
        note: rationale || null,
      },
    })
    return c.json({
      ok: true,
      id: signoff.id,
      decision: body.decision,
      logged: true,
      message: body.decision === 'approve'
        ? 'Human approval recorded. Claim elevated to verified status.'
        : 'Human rejection recorded. Claim suppressed from output.',
      auditTrail: { rowHash, createdAt: signoff.createdAt },
    })
  } catch (e) {
    return c.json({ error: e instanceof Error ? e.message : 'decision failed' }, 500)
  }
})

// Dynamic per-jurisdiction rule maturity, derived from statute convictions.
app.get('/jurisdictions/stats', (c) => {
  const stats = JURISDICTIONS.map((j) => {
    const statutes = STATUTES.filter((s) => s.jurisdiction === j.code)
    const sources = SOURCES.filter((s) => s.jurisdiction === j.code)
    const globalSources = SOURCES.filter((s) => !s.jurisdiction && (s.tier === 0 || s.tier === 1.5 || s.tier === 3))
    const verifiedStatutes = statutes.filter((s) => s.conviction === 'verified' || s.conviction === 'confirmed').length
    const registryScore = j.registry.conviction === 'verified' ? 40 : j.registry.conviction === 'inference' ? 15 : 5
    const feedScore = sources.length > 0 ? Math.round((sources.filter((s) => s.conviction === 'verified').length / sources.length) * 30) : 0
    const statuteScore = Math.min(30, statutes.length * 5)
    const dataSufficiency = Math.min(100, registryScore + feedScore + statuteScore)
    const maturity: 'production' | 'pilot' | 'development' | 'planned' =
      j.inPilot && statutes.length >= 3 && j.registry.conviction === 'verified' ? 'production' :
      j.inPilot ? 'pilot' :
      statutes.length >= 2 ? 'development' : 'planned'
    return {
      code: j.code, name: j.name, capital: j.capital, inPilot: j.inPilot,
      pilotResidents: j.pilotResidents,
      statutes: { total: statutes.length, verified: verifiedStatutes },
      sources: { jurisdictionSpecific: sources.length, global: globalSources.length },
      registryConviction: j.registry.conviction,
      registryName: j.registry.name,
      dataSufficiency, maturity,
    }
  })
  const ready = stats.filter((s) => s.maturity === 'production' || s.maturity === 'pilot').length
  const dev = stats.filter((s) => s.maturity === 'development').length
  const planned = stats.filter((s) => s.maturity === 'planned').length
  return c.json({
    generatedAt: new Date().toISOString(),
    summary: {
      total: JURISDICTIONS.length, ready, dev, planned,
      totalStatutes: STATUTES.length, totalSources: SOURCES.length,
    },
    jurisdictions: stats,
  })
})

