// Update a task (status, priority, owner, etc.)
app.patch('/competition/tasks/:id', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json().catch(() => ({}))
  const update: Record<string, unknown> = {}
  if (body.status !== undefined) {
    update.status = body.status
    if (body.status === 'done') update.completedAt = new Date()
  }
  if (body.priority !== undefined) update.priority = body.priority
  if (body.owner !== undefined) update.owner = body.owner
  if (body.title !== undefined) update.title = body.title
  if (body.description !== undefined) update.description = body.description
  const task = await prisma.competitionTask.update({ where: { id }, data: update })
  return c.json({ ok: true, task })
})

// Batch update: mark multiple tasks done.
app.post('/competition/tasks/batch', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const ids: string[] = body?.ids ?? []
  const status: string = body?.status ?? 'done'
  if (!ids.length) return c.json({ error: 'body.ids is required' }, 400)
  const update: Record<string, unknown> = { status }
  if (status === 'done') update.completedAt = new Date()
  const result = await prisma.competitionTask.updateMany({ where: { id: { in: ids } }, data: update })
  return c.json({ ok: true, updated: result.count })
})

