// ── Federation ────────────────────────────────────────────────────────────────
// Multi-jurisdiction instances with federated learning.
// Patterns (not data) propagate across the network.

const federationEngine = new FederationEngine()

// Register a jurisdiction instance.
app.post('/federation/instance', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const { code, name, status, dataSufficiency, patternCount, statuteCount, sourceCount } = body

  if (!code || !name) {
    return c.json({ error: 'code and name are required' }, 400)
  }

  federationEngine.registerInstance({
    code,
    name,
    status: status ?? 'active',
    dataSufficiency: dataSufficiency ?? 0,
    lastSync: new Date(),
    patternCount: patternCount ?? 0,
    statuteCount: statuteCount ?? 0,
    sourceCount: sourceCount ?? 0,
    version: '1.0.0',
  })

  return c.json({ ok: true, message: `Instance ${code} registered` })
})

// Get all registered instances.
