// ── Offline-First Architecture ─────────────────────────────────────────────────
// Works without internet. Deterministic engines run locally.
// LLM calls queue and sync when connected.

const offlineQueue = new OfflineQueue()
const localDataStore = new LocalDataStore()

// Get offline queue status.
app.get('/offline/queue/status', (c) => {
  return c.json({ ok: true, ...offlineQueue.getStatus() })
})

// Add operation to offline queue.
app.post('/offline/queue/enqueue', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const { action, endpoint, method, data } = body

  if (!action || !endpoint || !method) {
    return c.json({ error: 'action, endpoint, and method are required' }, 400)
  }

  const item = offlineQueue.enqueue(action, endpoint, method, data ?? {})
  return c.json({ ok: true, item })
})

// Process offline queue (when online).
app.post('/offline/queue/process', async (c) => {
  const result = await offlineQueue.processQueue()
  return c.json({ ok: true, ...result })
})

// Clear failed items from queue.
app.post('/offline/queue/clear-failed', (c) => {
  offlineQueue.clearFailed()
  return c.json({ ok: true, message: 'Failed items cleared' })
})

// Get local data store stats.
app.get('/offline/store/stats', (c) => {
  return c.json({ ok: true, ...localDataStore.getStats() })
})

// Store data locally.
app.post('/offline/store/set', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const { id, type, data } = body

  if (!id || !type || !data) {
    return c.json({ error: 'id, type, and data are required' }, 400)
  }

  localDataStore.set(id, type, data)
  return c.json({ ok: true, message: 'Data stored locally' })
})

// Get data from local store.
app.get('/offline/store/:id', (c) => {
  const id = c.req.param('id')
  const item = localDataStore.get(id)

  if (!item) {
    return c.json({ ok: false, error: 'Item not found' }, 404)
  }

  return c.json({ ok: true, item })
})

// Get all data of a type from local store.
app.get('/offline/store/type/:type', (c) => {
  const type = c.req.param('type')
  const items = localDataStore.getByType(type)
  return c.json({ ok: true, items, count: items.length })
})

// Get unsynced data from local store.
app.get('/offline/store/unsynced', (c) => {
  const items = localDataStore.getUnsynced()
  return c.json({ ok: true, items, count: items.length })
})

// Mark data as synced.
app.post('/offline/store/synced/:id', (c) => {
  const id = c.req.param('id')
  localDataStore.markSynced(id)
  return c.json({ ok: true, message: `Item ${id} marked as synced` })
})

// ── Learning Loop ──────────────────────────────────────────────────────────────
// Outcome tracking, conviction weight updates, and self-improvement.
// The system gets smarter with every use.

const learningEngine = new LearningEngine()

// Record a recommendation made by the system.
app.post('/learning/recommendation', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const { patternId, jurisdiction, claim, confidence, evidenceClass, madeBy } = body

  if (!patternId || !jurisdiction || !claim) {
    return c.json({ error: 'patternId, jurisdiction, and claim are required' }, 400)
  }

  const rec = learningEngine.recordRecommendation({
    patternId,
    jurisdiction,
    claim,
    confidence: confidence ?? 0.5,
    evidenceClass: evidenceClass ?? 'heuristic',
    madeBy: madeBy ?? 'code',
  })

  return c.json({ ok: true, recommendation: rec })
})

// Record an outcome for a recommendation.
app.post('/learning/outcome', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const { recommendationId, outcome, evidence, source } = body

  if (!recommendationId || !outcome) {
    return c.json({ error: 'recommendationId and outcome are required' }, 400)
  }

  if (!['favorable', 'unfavorable', 'neutral'].includes(outcome)) {
    return c.json({ error: 'outcome must be favorable, unfavorable, or neutral' }, 400)
  }

  const result = learningEngine.recordOutcome(
    recommendationId,
    outcome as OutcomeType,
    evidence ?? '',
    source ?? 'user_feedback',
  )

  if (!result) {
    return c.json({ error: 'Recommendation not found' }, 404)
  }

  return c.json({ ok: true, outcome: result })
})

// Get conviction weight for a pattern in a jurisdiction.
app.get('/learning/conviction/:patternId/:jurisdiction', (c) => {
  const patternId = c.req.param('patternId')
  const jurisdiction = c.req.param('jurisdiction')
  const conviction = learningEngine.getConviction(patternId, jurisdiction)

  if (!conviction) {
    return c.json({ ok: false, error: 'No conviction found' }, 404)
  }

  return c.json({ ok: true, conviction })
})

// Get all conviction weights.
app.get('/learning/convictions', (c) => {
  const convictions = learningEngine.getAllConvictions()
  return c.json({ ok: true, convictions, count: convictions.length })
})

// Get learning statistics.
app.get('/learning/stats', (c) => {
  const stats = learningEngine.getStats()
  return c.json({ ok: true, ...stats })
})

// Get improvement trajectory.
app.get('/learning/trajectory', (c) => {
  const trajectory = learningEngine.getImprovementTrajectory()
  return c.json({ ok: true, trajectory, count: trajectory.length })
})

// Export learning data for persistence.
app.get('/learning/export', (c) => {
  const data = learningEngine.exportData()
  return c.json({ ok: true, ...data })
})

