// Render a template with provided values.
app.post('/templates/:id/render', async (c) => {
  const template = await prisma.correspondenceTemplate.findUnique({
    where: { id: c.req.param('id') },
  })
  if (!template) return c.json({ error: 'Template not found' }, 404)

  const body = await c.req.json().catch(() => ({}))
  const variables: TemplateVariable[] = JSON.parse(template.variables || '[]')
  let text = template.body
  const missingRequired: string[] = []

  for (const variable of variables) {
    const value = body[variable.name] || variable.defaultValue || ''
    if (!value && variable.required) missingRequired.push(variable.name)
    text = text.replaceAll(`{{${variable.name}}}`, value || `[${variable.label}]`)
  }

  return c.json({ ok: true, text, missingRequired, subject: template.subject })
})

// Seed default templates for a jurisdiction.
app.post('/templates/seed', async (c) => {
  const body = await c.req.json().catch(() => ({}))
  const jurisdiction = body.jurisdiction || 'UK'
  const builtIn = TEMPLATES.filter(t => t.jurisdictionCode === jurisdiction)

  let created = 0
  for (const tmpl of builtIn) {
    const exists = await prisma.correspondenceTemplate.findFirst({
      where: { name: tmpl.name, jurisdictionCode: tmpl.jurisdictionCode },
    })
    if (!exists) {
      await prisma.correspondenceTemplate.create({
        data: {
          name: tmpl.name,
          jurisdictionCode: tmpl.jurisdictionCode,
          category: tmpl.category,
          subject: tmpl.subject,
          body: tmpl.body,
          legalRefs: JSON.stringify(tmpl.legalRefs),
          variables: JSON.stringify(tmpl.variables),
          tier: tmpl.tier,
          isOss: tmpl.isOss,
        },
      })
      created++
    }
  }
  return c.json({ ok: true, created, total: builtIn.length })
})

