// Add a signature to a document.
app.post('/signed-documents/:id/sign', async (c) => {
  const doc = await prisma.signedDocument.findUnique({
    where: { id: c.req.param('id') },
  })
  if (!doc) return c.json({ error: 'Document not found' }, 404)
  if (doc.status === 'sent' || doc.status === 'archived') {
    return c.json({ error: 'Document is no longer accepting signatures' }, 400)
  }

  const body = await c.req.json().catch(() => ({}))
  if (!body.memberId || !body.displayName) {
    return c.json({ error: 'memberId and displayName are required' }, 400)
  }

  // Check for duplicate
  const existing = await prisma.documentSignature.findUnique({
    where: { documentId_memberId: { documentId: doc.id, memberId: body.memberId } },
  })
  if (existing) return c.json({ error: 'Already signed' }, 400)

  const sig = await prisma.documentSignature.create({
    data: {
      documentId: doc.id,
      memberId: body.memberId,
      displayName: body.displayName,
      method: body.method || 'click',
    },
  })

  const newCount = doc.collectedSigs + 1
  const newStatus = newCount >= doc.requiredSigs ? 'ready' : doc.status
  await prisma.signedDocument.update({
    where: { id: doc.id },
    data: { collectedSigs: newCount, status: newStatus },
  })

  return c.json({ ok: true, signature: sig, collectedSigs: newCount, status: newStatus })
})

